-- =====================================================================
-- HYATHLON INSTALL · PART 3d · rehab wording: considerations, not medical advice
-- Run AFTER Parts 3, 3b and 3c. Contains no personal data. SQL Editor → New query → Run. One transaction.
-- =====================================================================
begin;
set local search_path = public, extensions;

-- 1) Rehab content v4: considerations, not medical advice ----------------
alter table public.rehab_programs alter column disclaimer set default 'Not medical advice. This section shares general considerations and example exercises commonly used for running injuries. It is not a diagnosis or a treatment plan. Always follow the advice of your doctor, physiotherapist or other medical professional, who can assess you individually. If you''re unsure about anything, check with them first.';


on conflict (key) do update set title=excluded.title, items=excluded.items, sort_order=excluded.sort_order;

delete from public.rehab_programs;
delete from public.return_to_run_plans;







on conflict (version) do nothing;

-- Check: should show 10 | 15
select (select count(*) from public.rehab_programs) as programs,
       (select count(*) from public.rehab_global_guidance) as guidance;

commit;
